mapper.select:
select
assets_receive.*, assets.name as assetsName, assets.no as assetsNo, concat(staff.name, case when staff.status = '离职' then '（离职）' else '' end) as staffName
from assets_receive
left join assets on assets_receive.assets_id = assets.id
left join staff on assets_receive.staff_id = staff.id

     and assets_receive.staff_id = #{staffId}
    and assets.name like concat('%', #{assetsName}, '%')
     and assets_receive.status = #{status}
     and assets_receive.return_status = #{returnStatus}

order by assets_receive.id desc
